-- RESIDENTIAL QUALIFICATION — MEASUREMENT B: the population Map 1 actually shows (ZIP mode),
-- and the per-ZIP before/after. Eligibility = authoritative whole-ZIP membership on a
-- boundary_complete ZIP, exactly as public.app_zip_projects_markers defines it. Read-only.
-- CASE generated by scripts/residential-qualify-sql.mjs. Every count is paired with its control.
with m as (
  select distinct mm.zcta5, mm.source_key
  from geo.zip_authoritative_membership mm
  join geo.maps_zip_geography_status s on s.zip = mm.zcta5 and s.status = 'boundary_complete'),
p as (
  select distinct on (a.source_key) a.source_key, a.registry_id, a.type_raw, a.name
  from public.app_projects a
  where a.record_kind='development' and a.type='Residential'
    and exists (select 1 from m where m.source_key = a.source_key)),
n as (select source_key, registry_id, (' ' || btrim(regexp_replace(lower(coalesce(type_raw,'')), '[^a-z0-9]+', ' ', 'g')) || ' ') as tr, (' ' || btrim(regexp_replace(lower(coalesce(name,'')), '[^a-z0-9]+', ' ', 'g')) || ' ') as nm from p),
v as (select source_key, registry_id, case when (tr || nm) ~ ' (subdivision|resubdivision|subdivisions|plat|plats|replat|preliminary plat|final plat|site plan|site development plan|sitedevelopment|planned development|planned unit development|master plan|land development) ' then 'DEVELOPMENT' when nm ~ '^ (hvac|electric|electrical|plumbing|plumb|mechanical|gas piping|gas appliances|venting|boiler|furnace|water heater|photovoltaic|solar|trade|trades|ele|mec|plu|sprinkler|irrigation|low voltage|alter|alters|alteration|alterations|remodel|remodeling|renovation|renovations|repair|repairs|replace|replacing|replacement|reroof|re roof|roofing|roof|siding|window|windows|deck|decks|porch|porches|fence|fencing|pool|pools|spa|shed|carport|garage|accessory|maintenance|demolition|demo|tear off|tear down|teardown|interior|finish basement|basement finish|addition|additions|relocation|move|sign|signs|fire damage|retaining wall|driveway|patio|awning|generator|ev charger|antenna|alt) ' then 'ROUTINE' when tr ~ '^ (new construction|new residential|new single family|new multi family|new multifamily|new apartment|new home|new homes|new house|new dwelling|new building|new bldg|new sfr|new sfd|residential new|construction residential|residential construction|site dev|sfd devel|ground up) ' or nm ~ '^ (new construction|new residential|new single family|new multi family|new multifamily|new apartment|new home|new homes|new house|new dwelling|new building|new bldg|new sfr|new sfd|residential new|construction residential|residential construction|site dev|sfd devel|ground up) ' then 'DEVELOPMENT' when tr ~ '^ (new|nb|dsp) ' and tr ~ ' (construction|home|homes|house|dwelling|dwellings|residence|residences|residential|duplex|apartment|apartments|townhome|townhomes|townhouse|condo|condominium|sfr|sfd|building|bldg|units|unit) ' then 'DEVELOPMENT' when nm ~ '^ (new|nb|dsp) ' and nm ~ ' (construction|home|homes|house|dwelling|dwellings|residence|residences|residential|duplex|apartment|apartments|townhome|townhomes|townhouse|condo|condominium|sfr|sfd|building|bldg|units|unit) ' then 'DEVELOPMENT' when (tr || nm) ~ ' (hvac|electric|electrical|plumbing|plumb|mechanical|gas piping|gas appliances|venting|boiler|furnace|water heater|photovoltaic|solar|trade|trades|ele|mec|plu|sprinkler|irrigation|low voltage|alter|alters|alteration|alterations|remodel|remodeling|renovation|renovations|repair|repairs|replace|replacing|replacement|reroof|re roof|roofing|roof|siding|window|windows|deck|decks|porch|porches|fence|fencing|pool|pools|spa|shed|carport|garage|accessory|maintenance|demolition|demo|tear off|tear down|teardown|interior|finish basement|basement finish|addition|additions|relocation|move|sign|signs|fire damage|retaining wall|driveway|patio|awning|generator|ev charger|antenna|alt) ' then 'ROUTINE' when (registry_id = 'denton-county-dev-permits' and tr in (' house ', ' duplex ', ' mobile home ')) or (registry_id = 'dekalb-county-building-permits' and tr in (' new homes ')) then 'DEVELOPMENT' else 'UNRESOLVED' end as verdict from n),
z as (select m.zcta5, v.verdict from m join v on v.source_key = m.source_key)
select 'objects_by_verdict:' || verdict as metric, count(distinct source_key)::text as value
  from v group by verdict
union all select 'objects_total_live_residential', count(distinct source_key)::text from v
union all select 'zips_with_residential_before', count(distinct zcta5)::text from z
union all select 'zips_with_residential_after', count(distinct zcta5)::text from z where verdict='DEVELOPMENT'
union all select 'zips_losing_residential_entirely',
  (select count(*)::text from (select zcta5 from z group by zcta5
     having count(*) filter (where verdict='DEVELOPMENT') = 0) q)
order by 1;
